{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "Security Alert Policy disables critical alerts (SQL Injection and Data Exfiltration)",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "HIGH",
      "explanation": "The 'disabled_alerts' list explicitly turns off 'Sql_Injection' and 'Data_Exfiltration', which are the most critical threats for an MSSQL server. This prevents Azure Defender from generating alerts for these specific attack vectors, leaving the database vulnerable to undetected compromise."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  disabled_alerts = []\n  retention_days  = 20\n  email_addresses = [\"securityengineer@bridgecrew.io\"]\n}",
  "fix_summary": "Removed 'Sql_Injection' and 'Data_Exfiltration' from the 'disabled_alerts' list to ensure that critical security threat detections remain enabled and alerting is active."
}
